		'roofing-marketing' => array( 'Roofing Marketing', '<h2>Compete across urgent repairs and planned replacements</h2><p>Roofing demand shifts with storms, insurance activity, seasonality, and local housing stock. A strong system separates repair, replacement, inspection, commercial, and storm-related intent while protecting lead quality.</p><h2>Recommended roofing growth system</h2><ul><li>Fast mobile pages for repair and replacement intent</li><li>Service-area SEO built on real market knowledge</li><li>Search and Local Services Ads where eligible</li><li>Call tracking and storm-campaign attribution</li><li>Estimate follow-up and review requests</li></ul>', 'Websites, SEO, paid media, and follow-up shaped around the roofing customer journey.' ),
		'hvac-marketing' => array( 'HVAC Marketing', '<h2>Balance emergency demand, maintenance, and replacement</h2><p>HVAC marketing needs to address urgent no-cool and no-heat searches, high-consideration system replacement, seasonal tune-ups, financing questions, and recurring maintenance plans.</p><h2>Recommended HVAC growth system</h2><ul><li>Clear emergency and replacement conversion paths</li><li>Local SEO by legitimate service area</li><li>Seasonal paid-search budget planning</li><li>Call, booking, and job-type tracking</li><li>Maintenance reminders and reactivation</li></ul>', 'Generate and convert HVAC demand across repairs, replacement, and maintenance.' ),
		'plumber-marketing' => array( 'Plumber Marketing', '<h2>Win high-intent local searches without wasting dispatch capacity</h2><p>Plumbing demand ranges from immediate leaks and clogs to water heaters and planned repiping. Campaign structure and page content should route each need to a clear, mobile-first next step.</p><h2>Recommended plumbing growth system</h2><ul><li>Emergency click-to-call experiences</li><li>Distinct pages for valuable service lines</li><li>Maps, organic, paid search, and LSA coverage</li><li>Service-area and schedule controls</li><li>Call quality and booked-job feedback</li></ul>', 'A local acquisition system shaped around urgent and planned plumbing services.' ),
		'electrician-marketing' => array( 'Electrician Marketing', '<h2>Connect homeowners with the right electrical service</h2><p>Customers search differently for emergency troubleshooting, panels, EV chargers, generators, lighting, and rewiring. Useful pages and campaign segmentation improve relevance and routing.</p>', 'Marketing for residential and commercial electrical service demand.' ),
		'locksmith-marketing' => array( 'Locksmith Marketing', '<h2>Build trust at the moment of urgent need</h2><p>Locksmith marketing depends on fast mobile experiences, clear service boundaries, real local credibility, accurate business information, call quality, and policy-compliant advertising.</p>', 'Policy-conscious local marketing for legitimate locksmith businesses.' ),
		'remodeling-marketing' => array( 'Remodeling Marketing', '<h2>Support a longer, visual buying journey</h2><p>Remodeling clients research portfolios, process, trust, budget fit, design capabilities, and project types before reaching out. Content, photography, project stories, qualification, and nurture matter more than urgency.</p>', 'A trust-rich marketing system for kitchen, bathroom, and whole-home remodeling.' ),
		'landscaping-marketing' => array( 'Landscaping Marketing', '<h2>Balance recurring service and high-value projects</h2><p>Landscape maintenance, design-build, irrigation, hardscaping, and seasonal services require different offers, search terms, visuals, and follow-up.</p>', 'Local visibility and lead generation for landscape service and design-build companies.' ),
		'concrete-marketing' => array( 'Concrete Contractor Marketing', '<h2>Show the work and qualify the project</h2><p>Concrete customers need clear project capabilities, service boundaries, proof of workmanship, timing expectations, and a simple way to describe the site and scope.</p>', 'Web, SEO, and paid acquisition for residential and commercial concrete work.' ),
		'general-contractor-marketing' => array( 'General Contractor Marketing', '<h2>Earn confidence for complex projects</h2><p>General contractors need a clear market position, strong project evidence, detailed capabilities, geographic relevance, and a qualification process suited to longer sales cycles.</p>', 'A credible digital growth system for general contractors and construction firms.' ),
	);
}
